<template>
  <div class="oi-form back-white">

    <div class="oi-cards">
      <div
        class="oi-card"
        v-for="metric_key in metric_keys"
        :key="metric_key"
      >
        <div class="oi-card-header">
          {{ $t(prepareTranslation(metric_key)) }}
        </div>
        <div class="oi-card-body">
          <span class="oi-card-label">{{ $t('data_amount') }}</span>
          <span class="oi-card-value">{{
            monthly_metric_counts[metric_key]
              ? monthly_metric_counts[metric_key]
              : 0
          }}</span>
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import dateUtil from 'src/utils/date';
import { supplierOrganisationApiService, userApiService } from 'src/services';
import { type dynamicObj, $ } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions';
export default defineComponent({
  el: '#app',
  mixins: [dateUtil],
  methods: {
    async prepareOrgMetrics() {
      try {
        this.loading = true;
        const monthmetric = await userApiService.getMonthlyOrgMetric();

        this.monthly_metric = monthmetric;
        for (let metric_key of this.metric_keys) {
          this.monthly_metric_counts[metric_key] =
            this.monthly_metric[metric_key + '_count'];
        }

        let data = new FormData();
        data.append('org_id', userApiService.getOrgId());

        const supplierOrganisations =
          await supplierOrganisationApiService.getApprovedSupplierOrganisations(
            data,
          );
        this.monthly_metric_counts['suppliers'] =
          supplierOrganisations.data.length;
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    prepareTranslation(translation_key: string): string {
      switch (translation_key) {
        case 'sub_orgs':
          return 'sub_org';
        default:
          return translation_key;
      }
    },
  },

  mounted: async function () {
    await this.prepareOrgMetrics();
  },
  setup() {
    return {
      loading: ref(false),
      monthly_metric: ref({} as dynamicObj),
      monthly_metric_counts: ref({} as dynamicObj),
      metric_keys: ['users', 'sub_orgs', 'suppliers'],
    };
  },
});
</script>

