<template>
  <div class="ss-form back-white">

    <template v-if="coreSubscriptions.length > 0">
      <div class="ss-cards">
        <template v-for="subscription in coreSubscriptions" :key="subscription.id">
          <div class="ss-card">
            <div class="ss-card-header">
              {{ subscription.plan_name }}
            </div>
            <div class="ss-card-days">
              <template v-if="subscription.days_remaining != null">
                {{ subscription.days_remaining > 0 ? subscription.days_remaining : 0 }}
                {{ $t('days_left') }}
              </template>
              <span v-else>&mdash;</span>
            </div>
            <div class="ss-card-dates">
              <div class="ss-card-date-row">
                <span>{{ $t('start_date') }}</span>
                <span>{{ formatDateAccordingToPreference(subscription.start_date, true) }}</span>
              </div>
              <div class="ss-card-date-row">
                <span>{{ $t('end_date') }}</span>
                <span>{{ formatDateAccordingToPreference(subscription.end_date, true) }}</span>
              </div>
            </div>
          </div>
        </template>
      </div>
    </template>

    <template v-else>
      <p class="ss-empty">{{ $t('no_subscription') }}</p>
    </template>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useSubscriptionStore } from 'src/store/User/subscription.store';
import { storeToRefs } from 'pinia';
import dateUtil from 'src/utils/date';
import type { FeatureSubscription } from 'src/sdk/auth/models/featureSubscription';

export default defineComponent({
  mixins: [dateUtil],
  computed: {
    coreSubscriptions(): FeatureSubscription[] {
      return this.feature_subscriptions.filter(
        (sub: FeatureSubscription) => !sub.plan_key,
      );
    },
  },
  setup() {
    const subscription_store = useSubscriptionStore();
    const { feature_subscriptions } = storeToRefs(subscription_store);
    return {
      feature_subscriptions,
    };
  },
});
</script>

